test('native Tab remembers board focus and matched cards stay focusable and inactive', async ({
  page,
}) => {
  await loadTimedBoard(page);
  const cards = page.locator('.card');
  await cards.nth(5).focus();
  await page.keyboard.press('Shift+Tab');
  await expect(page.getByRole('button', { name: DealControl.restart, exact: true })).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(cards.nth(5)).toBeFocused();
  await page.keyboard.press('ArrowLeft');
  await page.keyboard.press('Space');
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('Enter');
  await expect(page.locator('.card.matched')).toHaveCount(2);
  await expect(cards.nth(5)).toHaveAttribute('aria-disabled', 'true');
  await expect(cards.nth(5)).toBeFocused();
  await page.keyboard.press('Space');
  expect(await moves(page)).toBe(1);
  await page.keyboard.press('Tab');
  expect(await page.locator('.card:focus').count()).toBe(0);
});

test('Alt+ArrowLeft and Ctrl+End stay with the browser and leave the board alone', async ({
  page,
}) => {
  await loadTimedBoard(page);
  const card = page.locator('.card').nth(5);
  await card.focus();
  const url = page.url();
  for (const key of ['Alt+ArrowLeft', 'Control+End']) {
    await page.keyboard.press(key);
    await expect(card, `I06 ${key} keeps focus`).toBeFocused();
    await expect(page.locator('.card.revealed'), `I06 ${key} reveals no card`).toHaveCount(0);
  }
  expect(await moves(page)).toBe(0);
  expect(page.url()).toBe(url);
});
import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { SNAPSHOT_VERSION } from '../src/game/snapshot.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { boardCode, parseBoardCode } from '../src/game/deck.ts';
import { loadFixedBoard, PHONE } from './game-fixture.ts';
import { boardGaps } from './focus-bounds.ts';
import { moveKeyboardTo } from './accessibility-tree.ts';
import type { Page } from '@playwright/test';

const SIZE = 16;
// Row 7, column 11 sits past the right edge of a phone board scrolled back to its start.
const REMEMBERED = 6 * SIZE + 10;
// Row 15, column 16 sits past the right and bottom edges of that board.
const FAR = 14 * SIZE + 15;
const EXAMPLE_SIZE = parseBoardCode(EXAMPLE_CODE)?.size ?? 0;

async function scrollBoardToStart(page: Page): Promise<void> {
  await page.locator('.board-viewport').evaluate((viewport) => viewport.scrollTo(0, 0));
  await page.evaluate(() => new Promise((ready) => requestAnimationFrame(ready)));
}

test('Tab and Shift+Tab bring the remembered card in with nearest alignment', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(SIZE));
  const restart = page.getByRole('button', { name: DealControl.restart, exact: true });
  await restart.focus();
  await page.keyboard.press('Tab');
  await moveKeyboardTo(page, REMEMBERED, SIZE);
  const card = page.locator('.card').nth(REMEMBERED);
  for (const enter of ['Shift+Tab', 'Tab']) {
    if (enter === 'Shift+Tab') await page.keyboard.press('Tab');
    else await restart.focus();
    await scrollBoardToStart(page);
    await page.keyboard.press(enter);
    await expect(card).toBeFocused();
    const gaps = await boardGaps(card);
    expect(gaps.right, `I13 ${enter} enters with nearest alignment`).toBeCloseTo(gaps.margin, 0);
  }
});

test('Resume returns focus to the remembered card with nearest alignment', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.locator('summary').click();
  const paused = {
    version: SNAPSHOT_VERSION,
    boardCode: boardCode(SIZE, 1),
    matched: [],
    selection: { kind: SelectionKind.one, index: 0 },
    moves: 0,
    elapsedMs: 0,
    started: true,
  };
  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(JSON.stringify(paused));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await page.locator('.card').first().focus();
  await moveKeyboardTo(page, FAR, SIZE);
  const card = page.locator('.card').nth(FAR);
  await expect(card).toBeFocused();
  await scrollBoardToStart(page);
  await page.getByRole('button', { name: ReproductionControl.resume, exact: true }).click();
  await expect(card).toBeFocused();
  const gaps = await boardGaps(card);
  expect(gaps.right, 'I13 Resume returns with nearest alignment').toBeCloseTo(gaps.margin, 0);
  expect(gaps.bottom, 'I13 Resume returns with nearest alignment').toBeCloseTo(gaps.margin, 0);
});

test('every keyboard move after a pointer click shows the focus outline', async ({ page }) => {
  await loadFixedBoard(page);
  const cards = page.locator('.card');
  await cards.nth(5).click();
  for (const [key, index] of [
    ['ArrowRight', 6],
    ['ArrowDown', 6 + EXAMPLE_SIZE],
    ['ArrowLeft', 5 + EXAMPLE_SIZE],
    ['ArrowUp', 5],
  ] as const) {
    await page.keyboard.press(key);
    await expect(cards.nth(index)).toBeFocused();
    await expect(cards.nth(index), `V16 outline after ${key}`).toHaveCSS('outline-style', 'solid');
    await expect(cards.nth(index), `V16 outline after ${key}`).toHaveCSS('outline-width', '3px');
  }
});
import { expect, Scrollbars, test, TestTimeouts } from './browser-test.ts';
import { DealControl } from '../src/game/controls/control-labels.ts';
import { loadFixedBoard, PHONE } from './game-fixture.ts';
import { expectFocusInside } from './focus-bounds.ts';
import { moveKeyboardTo } from './accessibility-tree.ts';

for (const viewport of [PHONE, { width: 1280, height: 800 }, { width: 1280, height: 1400 }]) {
  test(`16x16 fits the page and keeps both end focus outlines at ${viewport.width}x${viewport.height}`, async ({
    page,
  }) => {
    await page.setViewportSize(viewport);
    await loadFixedBoard(page);
    await page.getByLabel(DealControl.size, { exact: true }).selectOption('16');
    await expect(page.locator('.card')).toHaveCount(256);
    const layout = await page.locator('.board-viewport').evaluate((element) => ({
      height: element.clientHeight,
      contentHeight: element.scrollHeight,
      pageWidth: document.documentElement.scrollWidth,
      viewportWidth: window.innerWidth,
      padding: getComputedStyle(element).padding,
    }));
    expect(layout.pageWidth).toBeLessThanOrEqual(layout.viewportWidth);
    expect(layout.height).toBeLessThanOrEqual(viewport.height * 0.7);
    expect(layout.height).toBeLessThanOrEqual(768);
    expect(layout.contentHeight).toBeGreaterThan(layout.height);
    expect(parseFloat(layout.padding)).toBe(6);
    const card = await page.locator('.card').first().boundingBox();
    expect(card?.width).toBeGreaterThanOrEqual(44);
    expect(card?.height).toBe(card?.width);
    await page.locator('.card').first().focus();
    await expectFocusInside(page.locator('.card').first());
    await moveKeyboardTo(page, 16 ** 2 - 1, 16);
    await expect(page.locator('.card').last()).toBeFocused();
    await expectFocusInside(page.locator('.card').last());
  }, {}, Scrollbars.hidden, TestTimeouts.long);
}

test('the default board fits a narrow phone and controls keep their target sizes', async ({
  page,
}) => {
  await page.setViewportSize({ width: 320, height: 640 });
  await loadFixedBoard(page);
  const viewport = await page.locator('.board-viewport').evaluate((element) => ({
    width: element.clientWidth,
    content: element.scrollWidth,
    page: document.documentElement.scrollWidth,
    window: window.innerWidth,
  }));
  expect(viewport.content).toBeLessThanOrEqual(viewport.width);
  expect(viewport.page).toBeLessThanOrEqual(viewport.window);
  for (const element of await page.locator('.controls button, .controls select, .card').all()) {
    const box = await element.boundingBox();
    expect(box?.height).toBeGreaterThanOrEqual(44);
    expect(box?.width).toBeGreaterThanOrEqual(44);
  }
});

const SIZE = 16;
// Reaching row 9, column 9 scrolls the board and the page with nearest alignment, so only the
// card's scroll margin keeps its outline in view.
const INTERIOR = 8 * SIZE + 8;

test('focus clearance survives nearest scroll to an interior card', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(SIZE));
  await page.getByRole('button', { name: DealControl.restart, exact: true }).focus();
  await page.keyboard.press('Tab');
  await expect(page.locator('.card').first()).toHaveCSS('outline-width', '3px');
  await expectFocusInside(page.locator('.card').first());
  await moveKeyboardTo(page, INTERIOR, SIZE);
  const interior = page.locator('.card').nth(INTERIOR);
  await expect(interior).toBeFocused();
  await expectFocusInside(interior);
});
